fn prime_num(n: u64) -> bool {
    // We assume n >= 2 as stated in the problem.
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }

    // Only check odd divisors from 3 up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;
    for k in (3..=limit).step_by(2) {
        if n % k == 0 {
            return false;
        }
    }

    true
}